import{_ as a,o as e,c as i,a4 as s}from"./chunks/framework.BUqnS5H7.js";const h=JSON.parse('{"title":"RabbitMQ 概览","description":"","frontmatter":{},"headers":[],"relativePath":"rabbitmq/01-basics/chapter-01-overview.md","filePath":"rabbitmq/01-basics/chapter-01-overview.md"}'),r={name:"rabbitmq/01-basics/chapter-01-overview.md"};function l(d,t,c,n,b,o){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="rabbitmq-概览" tabindex="-1" data-src-line="1" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">RabbitMQ 概览 <a class="header-anchor" href="#rabbitmq-概览" aria-label="Permalink to &quot;RabbitMQ 概览&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><p data-src-line="3" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">选 RabbitMQ 不是因为它&quot;最好&quot;，而是因为在&quot;业务消息 + 复杂路由 + 微秒级延迟&quot;这个组合需求下，它是最成熟的选择。</p></blockquote><h2 id="_1-rabbitmq-是什么" tabindex="-1" data-src-line="5" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">1. RabbitMQ 是什么 <a class="header-anchor" href="#_1-rabbitmq-是什么" aria-label="Permalink to &quot;1. RabbitMQ 是什么&quot;">​</a></h2><p data-src-line="7" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">RabbitMQ 是一个实现了 AMQP 0-9-1 协议的消息代理（Message Broker）。它的核心工作很简单：接收生产者发来的消息，根据路由规则投递给消费者。</p><p data-src-line="9" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">但&quot;简单&quot;不等于&quot;浅&quot;。在一个分布式系统里，&quot;可靠地把消息从 A 搬到 B&quot;这件事，涉及到消息持久化、确认机制、死信处理、集群高可用、网络分区恢复等一系列工程问题。RabbitMQ 用十几年的生产验证，把这些都解决了。</p><h2 id="_2-为什么需要消息队列" tabindex="-1" data-src-line="11" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">2. 为什么需要消息队列 <a class="header-anchor" href="#_2-为什么需要消息队列" aria-label="Permalink to &quot;2. 为什么需要消息队列&quot;">​</a></h2><p data-src-line="13" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">直接调用（HTTP/RPC）和消息队列，本质上解决的是不同的问题：</p><p data-src-line="15" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>直接调用</strong>：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>服务A ──HTTP──▶ 服务B</span></span>
<span class="line"><span>           等待响应</span></span>
<span class="line"><span>           ◀──────</span></span></code></pre></div><ul data-src-line="23" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><li data-src-line="23" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">强耦合：B 挂了 A 也挂</li><li data-src-line="24" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">同步阻塞：A 必须等 B 处理完</li><li data-src-line="25" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">无缓冲：突发流量直接打垮 B</li></ul><p data-src-line="27" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>消息队列</strong>：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>服务A ──▶ [Queue] ──▶ 服务B</span></span>
<span class="line"><span>         消息暂存      异步处理</span></span></code></pre></div><ul data-src-line="34" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><li data-src-line="34" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">解耦：A 只管发，不关心谁消费</li><li data-src-line="35" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">异步：A 发完就走，不等 B</li><li data-src-line="36" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">削峰：Queue 充当缓冲区，B 按自己的速率消费</li></ul><p data-src-line="38" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">但这不是说消息队列比直接调用&quot;更好&quot;。它引入了新的复杂性：消息丢失的风险、消费顺序问题、幂等性要求、运维成本。<strong>如果同步调用能满足需求，不要引入消息队列。</strong></p><h2 id="_3-rabbitmq-的核心优势" tabindex="-1" data-src-line="40" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">3. RabbitMQ 的核心优势 <a class="header-anchor" href="#_3-rabbitmq-的核心优势" aria-label="Permalink to &quot;3. RabbitMQ 的核心优势&quot;">​</a></h2><table tabindex="0"><thead data-src-line="42" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><tr data-src-line="42" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><th style="text-align:left;">维度</th><th style="text-align:left;">RabbitMQ 的特点</th><th style="text-align:left;">对比</th></tr></thead><tbody data-src-line="44" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><tr data-src-line="44" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">路由能力</td><td style="text-align:left;">4 种 Exchange，支持精确/模糊/广播路由</td><td style="text-align:left;">Kafka 只支持 Topic 级路由</td></tr><tr data-src-line="45" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">延迟</td><td style="text-align:left;">微秒级（Erlang 调度器优势）</td><td style="text-align:left;">Kafka 毫秒级</td></tr><tr data-src-line="46" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">协议支持</td><td style="text-align:left;">AMQP/MQTT/STOMP</td><td style="text-align:left;">Kafka 只有自定义协议</td></tr><tr data-src-line="47" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">死信队列</td><td style="text-align:left;">原生支持，配置即用</td><td style="text-align:left;">Kafka 不原生支持</td></tr><tr data-src-line="48" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">延迟消息</td><td style="text-align:left;">插件原生支持</td><td style="text-align:left;">Kafka 不原生支持</td></tr><tr data-src-line="49" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">运维复杂度</td><td style="text-align:left;">低（单节点即可用）</td><td style="text-align:left;">Kafka 至少 3 节点</td></tr><tr data-src-line="50" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">消息模型</td><td style="text-align:left;">Queue + Exchange（灵活组合）</td><td style="text-align:left;">Topic + Partition（固定）</td></tr></tbody></table><h2 id="_4-rabbitmq-不适合什么" tabindex="-1" data-src-line="52" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">4. RabbitMQ 不适合什么 <a class="header-anchor" href="#_4-rabbitmq-不适合什么" aria-label="Permalink to &quot;4. RabbitMQ 不适合什么&quot;">​</a></h2><table tabindex="0"><thead data-src-line="54" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><tr data-src-line="54" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><th style="text-align:left;">场景</th><th style="text-align:left;">问题</th><th style="text-align:left;">替代方案</th></tr></thead><tbody data-src-line="56" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><tr data-src-line="56" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">百万级 QPS</td><td style="text-align:left;">Erlang 单节点吞吐上限</td><td style="text-align:left;">Kafka / Pulsar</td></tr><tr data-src-line="57" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">大量消息堆积</td><td style="text-align:left;">堆积后性能下降（内存换页）</td><td style="text-align:left;">Kafka（顺序写磁盘）</td></tr><tr data-src-line="58" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">消息回溯</td><td style="text-align:left;">不支持按 offset 重新消费</td><td style="text-align:left;">Kafka</td></tr><tr data-src-line="59" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">流处理</td><td style="text-align:left;">无原生流处理引擎</td><td style="text-align:left;">Kafka Streams / Flink</td></tr><tr data-src-line="60" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">日志收集</td><td style="text-align:left;">高吞吐场景不是强项</td><td style="text-align:left;">Kafka</td></tr></tbody></table><p data-src-line="62" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>判断标准</strong>：如果你的需求是&quot;业务消息 + 可靠投递 + 灵活路由 + 低延迟&quot;，RabbitMQ 是首选。如果是&quot;大数据量 + 高吞吐 + 消息回溯&quot;，选 Kafka。</p><h2 id="_5-核心概念速览" tabindex="-1" data-src-line="64" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">5. 核心概念速览 <a class="header-anchor" href="#_5-核心概念速览" aria-label="Permalink to &quot;5. 核心概念速览&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Producer ──▶ Exchange ──binding──▶ Queue ──▶ Consumer</span></span>
<span class="line"><span>             (路由)               (存储)      (消费)</span></span></code></pre></div><ul data-src-line="71" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><li data-src-line="71" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>Producer</strong>：消息发送者，不直接发到 Queue，而是发到 Exchange</li><li data-src-line="72" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>Exchange</strong>：路由器，根据 binding 规则把消息分发到一个或多个 Queue</li><li data-src-line="73" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>Queue</strong>：消息的最终存储，消费者从这里取消息</li><li data-src-line="74" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>Binding</strong>：Exchange 和 Queue 之间的关联规则（routing key）</li><li data-src-line="75" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>Consumer</strong>：消息消费者，支持推模式（Push）和拉模式（Pull）</li><li data-src-line="76" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>Channel</strong>：轻量级连接，复用 TCP 连接，避免频繁建连开销</li><li data-src-line="77" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>Virtual Host（vhost）</strong>：逻辑隔离单元，类似数据库的 schema</li></ul><h2 id="_6-exchange-类型与路由能力" tabindex="-1" data-src-line="79" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">6. Exchange 类型与路由能力 <a class="header-anchor" href="#_6-exchange-类型与路由能力" aria-label="Permalink to &quot;6. Exchange 类型与路由能力&quot;">​</a></h2><table tabindex="0"><thead data-src-line="81" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><tr data-src-line="81" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><th style="text-align:left;">Exchange 类型</th><th style="text-align:left;">路由规则</th><th style="text-align:left;">典型场景</th></tr></thead><tbody data-src-line="83" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><tr data-src-line="83" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">Direct</td><td style="text-align:left;">routing key 精确匹配</td><td style="text-align:left;">点对点、任务分发</td></tr><tr data-src-line="84" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">Topic</td><td style="text-align:left;">routing key 通配符匹配（<code>*</code> 和 <code>#</code>）</td><td style="text-align:left;">事件订阅、分类路由</td></tr><tr data-src-line="85" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">Fanout</td><td style="text-align:left;">忽略 routing key，广播到所有绑定队列</td><td style="text-align:left;">广播通知、实时推送</td></tr><tr data-src-line="86" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">Headers</td><td style="text-align:left;">根据消息 headers 匹配</td><td style="text-align:left;">复杂条件路由（少用）</td></tr></tbody></table><p data-src-line="88" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">这是 RabbitMQ 最强的地方：通过 Exchange + Binding 的组合，可以实现几乎任意的消息路由拓扑。</p><h2 id="_7-可靠性保障层次" tabindex="-1" data-src-line="90" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">7. 可靠性保障层次 <a class="header-anchor" href="#_7-可靠性保障层次" aria-label="Permalink to &quot;7. 可靠性保障层次&quot;">​</a></h2><p data-src-line="92" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">RabbitMQ 的可靠性不是单一机制，而是多层叠加：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Producer                    Broker                     Consumer</span></span>
<span class="line"><span>  │                           │                           │</span></span>
<span class="line"><span>  ├─ Publisher Confirm ──▶    ├─ 持久化（Durable Queue）   ├─ Manual ACK</span></span>
<span class="line"><span>  ├─ Mandatory Return ──▶     ├─ 持久化（Persistent Msg）  ├─ Prefetch 控制</span></span>
<span class="line"><span>  │                           ├─ 镜像队列/Quorum Queue     ├─ 死信队列</span></span>
<span class="line"><span>  │                           └─ 事务（性能差，少用）       └─ 重试 + DLX</span></span></code></pre></div><p data-src-line="103" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">每一层解决不同的问题。生产环境通常需要至少 Publisher Confirm + Durable Queue + Manual ACK 的组合。</p><h2 id="_8-典型使用场景" tabindex="-1" data-src-line="105" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">8. 典型使用场景 <a class="header-anchor" href="#_8-典型使用场景" aria-label="Permalink to &quot;8. 典型使用场景&quot;">​</a></h2><h3 id="_8-1-电商订单流程" tabindex="-1" data-src-line="107" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">8.1 电商订单流程 <a class="header-anchor" href="#_8-1-电商订单流程" aria-label="Permalink to &quot;8.1 电商订单流程&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>下单 ──▶ order.exchange ──▶ order.created.queue ──▶ 库存服务（扣库存）</span></span>
<span class="line"><span>                        ──▶ order.created.queue ──▶ 通知服务（发短信）</span></span>
<span class="line"><span>                        ──▶ order.created.queue ──▶ 积分服务（加积分）</span></span></code></pre></div><p data-src-line="115" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">一条消息，多个消费者各自处理。Fanout 或 Topic Exchange 实现。</p><h3 id="_8-2-延迟任务" tabindex="-1" data-src-line="117" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">8.2 延迟任务 <a class="header-anchor" href="#_8-2-延迟任务" aria-label="Permalink to &quot;8.2 延迟任务&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>订单创建 ──▶ delay.exchange（延迟30分钟）──▶ order.timeout.queue ──▶ 检查支付状态</span></span></code></pre></div><p data-src-line="123" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">延迟消息插件（rabbitmq_delayed_message_exchange）实现。</p><h3 id="_8-3-rpc-调用" tabindex="-1" data-src-line="125" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">8.3 RPC 调用 <a class="header-anchor" href="#_8-3-rpc-调用" aria-label="Permalink to &quot;8.3 RPC 调用&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client ──▶ request.queue ──▶ Server</span></span>
<span class="line"><span>       ◀── reply.queue ◀──</span></span></code></pre></div><p data-src-line="132" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">RabbitMQ 原生支持 RPC 模式，适用于需要异步调用但又要返回结果的场景。</p><h2 id="_9-版本选择建议" tabindex="-1" data-src-line="134" data-src-file="rabbitmq/01-basics/chapter-01-overview.md">9. 版本选择建议 <a class="header-anchor" href="#_9-版本选择建议" aria-label="Permalink to &quot;9. 版本选择建议&quot;">​</a></h2><table tabindex="0"><thead data-src-line="136" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><tr data-src-line="136" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><th style="text-align:left;">版本</th><th style="text-align:left;">特点</th><th style="text-align:left;">建议</th></tr></thead><tbody data-src-line="138" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><tr data-src-line="138" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">3.13.x</td><td style="text-align:left;">最新稳定版，Quorum Queue 成熟</td><td style="text-align:left;">新项目首选</td></tr><tr data-src-line="139" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">3.12.x</td><td style="text-align:left;">稳定，社区活跃</td><td style="text-align:left;">生产环境可用</td></tr><tr data-src-line="140" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><td style="text-align:left;">3.11 及以下</td><td style="text-align:left;">镜像队列为主（已废弃）</td><td style="text-align:left;">不推荐新项目</td></tr></tbody></table><p data-src-line="142" data-src-file="rabbitmq/01-basics/chapter-01-overview.md"><strong>关键变化</strong>：3.x 版本中，镜像队列（Mirrored Queue）已被 Quorum Queue 取代。新项目应直接使用 Quorum Queue，不要用镜像队列。</p>`,42)])])}const m=a(r,[["render",l]]);export{h as __pageData,m as default};
